Section Segs.
Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma bx_A : forall (fx : FPState) regs m (s pixs skel rkel : Z) (v : pixv) (ret : word),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (pixs + 64 <= s - 80)%Z -> p_cmap v = 0%Z -> (p_d v = 8 \/ p_d v = 32)%Z ->
    (pixs mod 8 = 0)%Z ->
    (1 <= skel < 2 ^ 64)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 80)) 80 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixs -> getr regs 11 = Z_to_bv 64 skel -> getr regs 12 = Z_to_bv 64 rkel ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x3ab58 : word) m rom) (@mkst fx regs' (0x3ac18 : word) (FRX m s ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 8 = Z_to_bv 64 skel /\ getr regs' 9 = Z_to_bv 64 pixs /\ getr regs' 18 = Z_to_bv 64 rkel
      /\ getr regs' 10 = Z_to_bv 64 (p_d v)
      /\ regs_agree (fun x => In x [1; 2; 8; 9; 10; 11; 18]%list) regs regs'.
Proof.
    intros fx regs m s pixs skel rkel v ret Hs Hs64 Hp1 PX Hps Hcm Hd ALp Hsk SOK H2 H1 H10 H11 H12.
    pose proof PX as (Hp0 & Hp64 & WF & _).
    assert (Hdr : (0 <= p_d v < 2 ^ 31)%Z) by lia.
    destruct Hd as [D8 | D32]; eexists; split.
    - zv F_2e300 D_2e300 (Z_to_bv 64 (s - 80)).
      stepST F_2e304 D_2e304 (Z_to_bv 64 (s - 8)) ret ltac:(sok_in SOK).
      stepST F_2e308 D_2e308 (Z_to_bv 64 (s - 16)) (getr regs 8) ltac:(sok_in SOK).
      stepST F_2e30c D_2e30c (Z_to_bv 64 (s - 24)) (getr regs 9) ltac:(sok_in SOK).
      stepST F_2e310 D_2e310 (Z_to_bv 64 (s - 32)) (getr regs 18) ltac:(sok_in SOK).
      stepST F_2e314 D_2e314 (Z_to_bv 64 (s - 40)) (getr regs 19) ltac:(sok_in SOK).
      stepST F_2e318 D_2e318 (Z_to_bv 64 (s - 48)) (getr regs 20) ltac:(sok_in SOK).
      stepb_ft F_2e31c D_2e31c ltac:(condZ).
      sn F_2e320 D_2e320. sn F_2e324 D_2e324. sn F_2e328 D_2e328.
      sn F_2e32c D_2e32c.
      stepb_ft F_1a9f0 D_1a9f0 ltac:(condZ).
      guard8 F_1a9f4 D_1a9f4 ALp.
      stepb_ft F_1a9f8 D_1a9f8 ltac:(condZ).
      stepLD F_1a9fc D_1a9fc (Z_to_le_bytes 8 (p_cmap v)) (Z_to_bv 64 0)
        ltac:(addr_norm; repeat rdn_peel1; exact (PIX_rd_cmap SEGS _ _ _ PX)) ltac:(rewrite Hcm; apply lez8; lia).
      stepret F_1aa00 D_1aa00 (0x3ab88 : word) ltac:(bveq).
      stepb_tk F_2e330 D_2e330 ltac:(condZ).
      sn F_2e3a4 D_2e3a4.
      sn F_2e3a8 D_2e3a8.
      stepb_ft F_1a8cc D_1a8cc ltac:(condZ).
      guard8 F_1a8d0 D_1a8d0 ALp.
      stepb_ft F_1a8d4 D_1a8d4 ltac:(condZ).
      stepLD F_1a8d8 D_1a8d8 (Z_to_le_bytes 4 (p_d v)) (Z_to_bv 64 (p_d v))
        ltac:(addr_norm; repeat rdn_peel1; exact (PIX_rd_d SEGS _ _ _ PX)) ltac:(apply lez4; lia).
      rewrite (v_lw_small (p_d v)) by lia.
      stepret F_1a8dc D_1a8dc (0x3ac04 : word) ltac:(bveq).
      zv F_2e3ac D_2e3ac (Z_to_bv 64 8).
      stepb_tk F_2e3b0 D_2e3b0 ltac:(condZ).
      stepb_ft F_2e3bc D_2e3bc ltac:(condZ).
      apply mst_refl.
    - repeat split; try solve_regs_agree; gres; pin; try reflexivity.
    - zv F_2e300 D_2e300 (Z_to_bv 64 (s - 80)).
      stepST F_2e304 D_2e304 (Z_to_bv 64 (s - 8)) ret ltac:(sok_in SOK).
      stepST F_2e308 D_2e308 (Z_to_bv 64 (s - 16)) (getr regs 8) ltac:(sok_in SOK).
      stepST F_2e30c D_2e30c (Z_to_bv 64 (s - 24)) (getr regs 9) ltac:(sok_in SOK).
      stepST F_2e310 D_2e310 (Z_to_bv 64 (s - 32)) (getr regs 18) ltac:(sok_in SOK).
      stepST F_2e314 D_2e314 (Z_to_bv 64 (s - 40)) (getr regs 19) ltac:(sok_in SOK).
      stepST F_2e318 D_2e318 (Z_to_bv 64 (s - 48)) (getr regs 20) ltac:(sok_in SOK).
      stepb_ft F_2e31c D_2e31c ltac:(condZ).
      sn F_2e320 D_2e320. sn F_2e324 D_2e324. sn F_2e328 D_2e328.
      sn F_2e32c D_2e32c.
      stepb_ft F_1a9f0 D_1a9f0 ltac:(condZ).
      guard8 F_1a9f4 D_1a9f4 ALp.
      stepb_ft F_1a9f8 D_1a9f8 ltac:(condZ).
      stepLD F_1a9fc D_1a9fc (Z_to_le_bytes 8 (p_cmap v)) (Z_to_bv 64 0)
        ltac:(addr_norm; repeat rdn_peel1; exact (PIX_rd_cmap SEGS _ _ _ PX)) ltac:(rewrite Hcm; apply lez8; lia).
      stepret F_1aa00 D_1aa00 (0x3ab88 : word) ltac:(bveq).
      stepb_tk F_2e330 D_2e330 ltac:(condZ).
      sn F_2e3a4 D_2e3a4.
      sn F_2e3a8 D_2e3a8.
      stepb_ft F_1a8cc D_1a8cc ltac:(condZ).
      guard8 F_1a8d0 D_1a8d0 ALp.
      stepb_ft F_1a8d4 D_1a8d4 ltac:(condZ).
      stepLD F_1a8d8 D_1a8d8 (Z_to_le_bytes 4 (p_d v)) (Z_to_bv 64 (p_d v))
        ltac:(addr_norm; repeat rdn_peel1; exact (PIX_rd_d SEGS _ _ _ PX)) ltac:(apply lez4; lia).
      rewrite (v_lw_small (p_d v)) by lia.
      stepret F_1a8dc D_1a8dc (0x3ac04 : word) ltac:(bveq).
      zv F_2e3ac D_2e3ac (Z_to_bv 64 8).
      stepb_ft F_2e3b0 D_2e3b0 ltac:(condZ).
      zv F_2e3b4 D_2e3b4 (Z_to_bv 64 32).
      stepb_ft F_2e3b8 D_2e3b8 ltac:(condZ).
      stepb_ft F_2e3bc D_2e3bc ltac:(condZ).
      apply mst_refl.
    - repeat split; try solve_regs_agree; gres; pin; try reflexivity.
  Qed.

  (* [comment removed for export] *)
  Lemma bx_T8 : forall (fx : FPState) regs r0 m (s pixs skel rkel : Z) (ret : word),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> cellsZ m (framex s ret r0) ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 8 = Z_to_bv 64 skel -> getr regs 9 = Z_to_bv 64 pixs -> getr regs 18 = Z_to_bv 64 rkel ->
    getr regs 10 = Z_to_bv 64 8 ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x3ac18 : word) m rom) (@mkst fx regs' (0x3ad78 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 11 = Z_to_bv 64 skel /\ getr regs' 12 = Z_to_bv 64 rkel
      /\ (forall x, In x [8; 9; 18; 19; 20]%bv -> getr regs' x = getr r0 x)
