  Lemma bx_T32 : forall (fx : FPState) regs m (pixs : Z),
    getr regs 9 = Z_to_bv 64 pixs -> getr regs 10 = Z_to_bv 64 32 ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x3ac18 : word) m rom) (@mkst fx regs' (0x1b5fc : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 11 = Z_to_bv 64 0 /\ getr regs' 1 = Z_to_bv 64 0x3accc
      /\ regs_agree (fun x => In x [1; 10; 11]%list) regs regs'.
