      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 8 = Z_to_bv 64 d0 /\ getr regs' 10 = Z_to_bv 64 (s - 64) /\ getr regs' 1 = Z_to_bv 64 0x3ad60
      /\ regs_agree (fun x => In x [1; 8; 10]%list) regs regs'.
