  (* [comment removed for export] *)
  Lemma bx_F2 : forall (fx : FPState) regs m (s : Z),
    getr regs 2 = Z_to_bv 64 (s - 80) ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x3ad60 : word) m rom) (@mkst fx regs' (0x1982c : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 10 = Z_to_bv 64 (s - 72) /\ getr regs' 1 = Z_to_bv 64 0x3ad68
      /\ regs_agree (fun x => In x [1; 10]%list) regs regs'.
Proof.
