  (* [comment removed for export] *)
  Lemma bx_E : forall (fx : FPState) regs r0 m (s d0 : Z) (ret : word),
    (80 <= s)%Z -> (s < 2 ^ 64)%Z -> ret_ok ret -> cellsZ m (framex s ret r0) ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 8 = Z_to_bv 64 d0 ->
    exists regs',
      msteps SEGS (@mkst fx regs (0x3ad70 : word) m rom) (@mkst fx regs' ret m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = Z_to_bv 64 d0
      /\ (forall x, In x [8; 9; 18; 19; 20]%bv -> getr regs' x = getr r0 x)
